class LmdbStreamingPreflightTest {
	private static final SimpleValueFactory VF = SimpleValueFactory.getInstance();
	private static final IRI PREDICATE = VF.createIRI("urn:streaming-preflight:predicate");
	private static final long MAP_SIZE = 64L * 1024 * 1024;
	private static final int STATEMENT_COUNT = 16;

	@Test
	void ordinaryPrepareTraversesBufferedModelWithoutArrayCopies(@TempDir File dataDir) throws Exception {
		try (TestStore fixture = new TestStore(dataDir)) {
			fixture.addBufferedStatements();
			fixture.branch.resetCounts();

			fixture.branch.prepare();

			assertTrue(fixture.branch.rowsVisited() > 0, "prepare must traverse actual buffered model rows");
			assertEquals(0, fixture.branch.arrayCopies(), "prepare must not copy the buffered model into an array");
		}
	}

	@Test
	void frozenPrepareTraversesBufferedModelWithoutArrayCopies(@TempDir File dataDir) throws Exception {
		try (TestStore fixture = new TestStore(dataDir)) {
			fixture.addBufferedStatements();
			fixture.branch.resetCounts();
			SailSource.FlushBatch batch = fixture.branch.freezeForFlush();
			try {
				fixture.branch.prepare();

				assertTrue(fixture.branch.rowsVisited() > 0, "frozen prepare must traverse actual buffered model rows");
				assertEquals(0, fixture.branch.arrayCopies(),
						"frozen prepare must not copy the buffered model into an array");
			} finally {
				batch.close();
			}
		}
	}

	@Test
	void repeatedPrepareChecksCachedPreflightBeforeTraversingModel(@TempDir File dataDir) throws Exception {
		try (TestStore fixture = new TestStore(dataDir)) {
			fixture.addBufferedStatements();
			fixture.branch.resetCounts();

			fixture.branch.prepare();

			assertTrue(fixture.branch.rowsVisited() > 0, "initial prepare must traverse actual buffered model rows");
			fixture.branch.resetCounts();

			fixture.branch.prepare();

			assertEquals(0, fixture.branch.rowsVisited(),
					"unchanged preflight must be recognized before model traversal");
			assertEquals(0, fixture.branch.arrayCopies(),
					"unchanged preflight must not copy the buffered model into an array");
		}
	}

	@Test
	void nestedUnionPreflightTraversesEveryDisjointExplicitAndInferredBranchWithoutArrayCopies(
			@TempDir File dataDir) throws Exception {
		try (TestStore fixture = new TestStore(dataDir)) {
			StreamingPreflightBranchFactory inferred = fixture.newInferredBranch();
			StreamingPreflightBranchFactory secondExplicit = fixture.newExplicitBranch();
			SailSource nested = StreamingPreflightBranchFactory.union(inferred.branch(), secondExplicit.branch());
			try (SailSource union = StreamingPreflightBranchFactory.union(fixture.branch.branch(), nested)) {
				fixture.addBufferedStatements(fixture.branch, "explicit-primary", STATEMENT_COUNT);
				fixture.addBufferedStatements(inferred, "inferred-additional", STATEMENT_COUNT);
				fixture.addBufferedStatements(secondExplicit, "explicit-nested", STATEMENT_COUNT);
				fixture.branch.resetCounts();
				inferred.resetCounts();
				secondExplicit.resetCounts();

				union.prepare();

				assertRowsVisited(fixture.branch, "outer primary must traverse actual buffered rows");
				assertRowsVisited(inferred, "nested inferred additional must traverse actual buffered rows");
				assertRowsVisited(secondExplicit, "nested explicit additional must traverse actual buffered rows");
				assertAll("no nested branch may copy its buffered model into an array",
						() -> assertNoArrayCopies(fixture.branch, "outer primary"),
						() -> assertNoArrayCopies(inferred, "nested inferred additional"),
						() -> assertNoArrayCopies(secondExplicit, "nested explicit additional"));
			}
		}
	}

	@Test
	void repeatedNestedUnionPrepareSkipsCoveredBranchTraversal(@TempDir File dataDir) throws Exception {
		try (TestStore fixture = new TestStore(dataDir)) {
			StreamingPreflightBranchFactory inferred = fixture.newInferredBranch();
			StreamingPreflightBranchFactory secondExplicit = fixture.newExplicitBranch();
			SailSource nested = StreamingPreflightBranchFactory.union(inferred.branch(), secondExplicit.branch());
			try (SailSource union = StreamingPreflightBranchFactory.union(fixture.branch.branch(), nested)) {
				fixture.addBufferedStatements(fixture.branch, "repeat-explicit-primary", STATEMENT_COUNT);
				fixture.addBufferedStatements(inferred, "repeat-inferred-additional", STATEMENT_COUNT);
				fixture.addBufferedStatements(secondExplicit, "repeat-explicit-nested", STATEMENT_COUNT);
				fixture.branch.resetCounts();
				inferred.resetCounts();
				secondExplicit.resetCounts();

				union.prepare();

				assertRowsVisited(fixture.branch, "first prepare must traverse outer primary");
				assertRowsVisited(inferred, "first prepare must traverse nested inferred additional");
				assertRowsVisited(secondExplicit, "first prepare must traverse nested explicit additional");
				fixture.branch.resetCounts();
				inferred.resetCounts();
				secondExplicit.resetCounts();

				union.prepare();

				assertAll("unchanged nested preflight must be covered before branch traversal",
						() -> assertEquals(0, fixture.branch.rowsVisited(),
								"unchanged outer primary must be covered before traversal"),
						() -> assertEquals(0, inferred.rowsVisited(),
								"unchanged nested inferred branch must be covered before traversal"),
						() -> assertEquals(0, secondExplicit.rowsVisited(),
								"unchanged nested explicit branch must be covered before traversal"),
						() -> assertNoArrayCopies(fixture.branch, "unchanged outer primary"),
						() -> assertNoArrayCopies(inferred, "unchanged nested inferred branch"),
						() -> assertNoArrayCopies(secondExplicit, "unchanged nested explicit branch"));
			}
		}
	}

	@Test
	void preflightFailureAfterPartialModelCursorClosesOpenedCursor(@TempDir File dataDir) throws Exception {
		try (TestStore fixture = new TestStore(dataDir)) {
			fixture.addBufferedStatements();
			fixture.branch.resetCounts();
			RuntimeException expectedFailure = new IllegalStateException("model cursor failed after its second row");
			fixture.branch.failAfterSecondNext(expectedFailure);

			Throwable actualFailure = assertThrows(Throwable.class, fixture.branch::prepare);

			assertTrue(fixture.branch.cursorOpens() > 0,
					"prepare must open a real model cursor before the injected failure");
			assertTrue(fixture.branch.rowsVisited() >= 2,
					"the tracking iterator calls its delegate twice before throwing the marker");
			assertSame(expectedFailure, actualFailure, "preflight must preserve the injected cursor failure");
			assertEquals(fixture.branch.cursorOpens(), fixture.branch.cursorCloses(),
					"every model cursor opened by failed preflight must be closed");
		}
	}

	@Test
	void additionalBufferedStatementInvalidatesCachedPreflight(@TempDir File dataDir) throws Exception {
		try (TestStore fixture = new TestStore(dataDir)) {
			fixture.addBufferedStatements();
			fixture.branch.resetCounts();

			fixture.branch.prepare();

			assertRowsVisited(fixture.branch, "initial 16-row preflight must activate");
			fixture.addBufferedStatements(fixture.branch, "additional-after-prepare", 1);
			fixture.branch.resetCounts();

			fixture.branch.prepare();

			assertTrue(fixture.branch.rowsVisited() > 0,
					"a newly buffered seventeenth statement must invalidate prior preflight coverage");
			assertNoArrayCopies(fixture.branch, "preflight after the additional buffered statement");
		}
	}

	private static void assertRowsVisited(StreamingPreflightBranchFactory branch, String message) {
		assertTrue(branch.rowsVisited() > 0, message);
	}

	private static void assertNoArrayCopies(StreamingPreflightBranchFactory branch, String name) {
		assertEquals(0, branch.arrayCopies(), name + " must not copy its buffered model into an array");
	}

	private static final class TestStore implements AutoCloseable {
		private final LmdbStore store;
		private final Object owner = new Object();
		private final StreamingPreflightBranchFactory branch;

		private TestStore(File dataDir) throws Exception {
			LmdbStoreConfig config = new LmdbStoreConfig("spoc")
					.setTripleDBSize(MAP_SIZE)
					.setValueDBSize(MAP_SIZE);
			store = new LmdbStore(dataDir, config);
			store.init();
			SailSource backing = store.getBackingStore().getExplicitSailSource(owner);
			branch = StreamingPreflightBranchFactory.create(backing);
		}

		private StreamingPreflightBranchFactory newExplicitBranch() {
			return StreamingPreflightBranchFactory.create(store.getBackingStore().getExplicitSailSource(owner));
		}

		private StreamingPreflightBranchFactory newInferredBranch() {
			return StreamingPreflightBranchFactory.create(store.getBackingStore().getInferredSailSource(owner));
		}

		private void addBufferedStatements() throws Exception {
			addBufferedStatements(branch, "buffered", STATEMENT_COUNT);
		}

		private void addBufferedStatements(StreamingPreflightBranchFactory target, String scope, int count)
				throws Exception {
			try (SailSink sink = target.branch().sink(IsolationLevels.SNAPSHOT)) {
				for (int index = 0; index < count; index++) {
					Statement statement = VF.createStatement(
							VF.createIRI("urn:streaming-preflight:subject:" + scope + ":" + index),
							PREDICATE,
							VF.createLiteral("value-" + scope + "-" + index));
					sink.approve(statement);
				}
				sink.flush();
			}
		}

		@Override
		public void close() throws Exception {
			try {
				branch.close();
			} finally {
				store.shutDown();
			}
		}
	}
}
